-- AL: primary_winner should be Tommy Tuberville (R won primary)
UPDATE governor_races SET primary_winner = 'Tommy Tuberville', primary_party = 'R' WHERE state_code = 'AL';
-- ID: primary_winner should be Brad Little (R won primary), not Scott Bedke
UPDATE governor_races SET primary_winner = 'Brad Little', primary_party = 'R' WHERE state_code = 'ID';
-- NE: primary_winner is Jim Pillen (R) - correct, leave as is
-- OH: primary_winner is Amy Acton (D) - but Ramaswamy won R primary, so primary_winner should be Ramaswamy (R)
UPDATE governor_races SET primary_winner = 'Vivek Ramaswamy', primary_party = 'R' WHERE state_code = 'OH';
-- OR: primary_winner is Tina Kotek (D) - but Drazan won R primary, so primary_winner should reflect both
-- Actually primary_winner field tracks the most notable primary winner - leave OR as Tina Kotek (D incumbent)
-- PA: primary_winner shows Josh Shapiro but dem_candidate was wrong - now fixed
UPDATE governor_races SET primary_winner = 'Josh Shapiro', primary_party = 'D' WHERE state_code = 'PA';

